"""PSLE-style items for sci-cycles-water-cycle (file sci-water-cycle.json), all tiers (round sci-fill-wcycle-2026-11-20).

Scope: outcome 1 evaporation/condensation/rain/run-off, Sun drives the cycle, fresh water supply; outcome 2 water and
life processes (transport, food making, sweat, wilting, habitat); outcome 3 water pollution and saving water.
Definitions: evaporation turns liquid water into invisible water vapour; condensation turns water vapour into tiny
droplets (clouds are tiny droplets); rain falls when droplets join and get too heavy to stay up.
"""
from fillkit import add, table, graph, lint
from figs_wcycle import cycle, bowl, pair, can

SUB, FILE = "sci-cycles-water-cycle", "sci-water-cycle.json"
WC, RD = "sci-pat-water-cycle", "sci-pat-read-data"
B, I, C = "basic", "intermediate", "competent"
P = []
def q(*a): P.append(a)
def W(t, tag, why): return (t, tag, why)
def cy(L=None, cap="The water cycle"): return lambda: cycle(L, cap)
def tb(h, r, w, c): return lambda: table(h, r, w, c)

# ---------------- basic ----------------
q("wc-001", B, 1, WC, "Which source of energy drives the water cycle?", "Heat from the Sun", [W("Wind blowing over the sea", "wrong-source", "Wind moves clouds, but it does not give the heat that changes water into water vapour."), W("Light from the Moon", "wrong-source", "The Moon gives very little light and no useful heat."), W("Cold air from the clouds", "wrong-source", "Cold air takes heat away. It cannot make water evaporate.")], ["The Sun's heat makes water evaporate, which starts the water cycle."], None)
q("wc-002", B, 1, WC, "What is the name of the process that changes water from a pond into water vapour?", "Evaporation", [W("Condensation", "reversed", "Condensation changes water vapour into liquid water."), W("Melting", "wrong-term", "Melting changes a solid into a liquid."), W("Freezing", "wrong-term", "Freezing changes a liquid into a solid.")], ["Liquid water changing into water vapour is evaporation."], None)
q("wc-003", B, 1, WC, "Which of the following describes water vapour?", "Water as an invisible gas", [W("Tiny drops of water that we can see", "confused-with-cloud", "Tiny visible drops are liquid water, as in clouds and mist."), W("Small pieces of ice in the air", "wrong-idea", "Ice is solid water, not water vapour."), W("Smoke made when water is heated", "wrong-idea", "Smoke is made of solid bits from burning things.")], ["Water vapour is a gas. We cannot see it."], None)
q("wc-004", B, 1, WC, "What happens to water vapour when it cools high up in the air?", "It condenses into tiny water droplets", [W("It melts into a block of ice up high", "wrong-term", "Melting is for solids."), W("It evaporates again and rises higher", "reversed", "Evaporation needs heat and changes liquid water into water vapour."), W("It becomes smoke and drifts away with the wind", "wrong-idea", "Water vapour does not turn into smoke.")], ["Cooling water vapour condenses into tiny water droplets."], None)
q("wc-005", B, 1, WC, "Look at the cloud in the picture. What is it made up of?", "tiny droplets of water", [W("water vapour only", "confused-with-gas", "Water vapour is invisible. We see clouds because of the liquid droplets."), W("smoke from factories", "wrong-idea", "Smoke is not what clouds are made of."), W("pieces of cotton-like dust", "wrong-idea", "Clouds have no dust fibres like cotton.")], ["Clouds are tiny water droplets formed by condensation."], lambda: cycle({"co": "Q"}, "Look at the cloud over the sea"))
q("wc-006", B, 1, WC, "Why does rain fall from a cloud?", "The droplets join and get too heavy to stay up", [W("The Sun pulls the water down to the ground", "wrong-idea", "The Sun gives heat. It does not pull water down."), W("The cloud has used up all of its water vapour", "wrong-idea", "Rain is made from the water droplets in the cloud."), W("The wind turns the whole cloud into solid ice", "wrong-idea", "Wind moves clouds, but it does not make rain by itself.")], ["Droplets join into bigger drops. When they are too heavy they fall as rain."], cy({"pr": "R"}, "Rain falls from the cloud in the water cycle"))
q("wc-007", B, 1, WC, "Hot water is covered with a plastic sheet. After some time, drops of water form under the sheet. What do the drops show?", "Water vapour has changed to liquid water", [W("The plastic sheet has made new water from air", "wrong-idea", "Water is not made by plastic. It comes from the bowl."), W("The hot water has frozen onto the sheet", "wrong-idea", "Hot water does not freeze."), W("The water has become heavier and fallen", "wrong-idea", "The water has only changed from vapour to liquid.")], ["Water vapour from the hot water cooled at the sheet and condensed into drops."], lambda: bowl("A model of the water cycle", ice=False))
q("wc-008", B, 1, WC, "Look at the picture of the water cycle. Which letter shows condensation?", "Q", [W("P", "wrong-stage", "P is water leaving the sea as water vapour. That is evaporation."), W("R", "wrong-stage", "R is rain falling from the cloud."), W("S", "wrong-stage", "S is water flowing back to the sea.")], ["Condensation happens in the cloud, at Q."], cy())
q("wc-009", B, 1, WC, "Look at the picture of the water cycle. Which letter shows evaporation?", "R", [W("P", "wrong-stage", "P is where droplets form in the cloud."), W("Q", "wrong-stage", "Q shows water flowing along the river."), W("S", "wrong-stage", "S is rain falling down.")], ["Water from the sea rises as water vapour, shown by R."], cy({"ev": "R", "co": "P", "pr": "S", "ru": "Q"}))
q("wc-010", B, 1, WC, "Look at the picture of the water cycle. Which letter shows rain falling?", "S", [W("P", "wrong-stage", "P is water rising from the sea."), W("Q", "wrong-stage", "Q is the cloud, where the droplets form."), W("R", "wrong-stage", "R is water flowing in the river.")], ["The dotted arrow from the cloud to the mountain is rain, S."], cy({"ev": "P", "co": "Q", "pr": "S", "ru": "R"}))
q("wc-011", B, 1, WC, "Look at the picture of the water cycle. Which letter shows river water flowing back to the sea?", "P", [W("Q", "wrong-stage", "Q is rising water vapour."), W("R", "wrong-stage", "R is the cloud."), W("S", "wrong-stage", "S is rain falling from the cloud.")], ["The river carries water down to the sea, shown by P."], cy({"ev": "Q", "co": "R", "pr": "S", "ru": "P"}))
q("wc-012", B, 1, WC, "Why does the Earth not run out of water even though water evaporates all the time?", "The water keeps moving around sea, air and land", [W("The Sun makes a lot of new water every day", "wrong-idea", "The Sun only gives heat. It does not make water."), W("New water is made inside the clouds each day", "wrong-idea", "Clouds are formed from water that evaporated earlier."), W("Only a very little water evaporates from the sea", "wrong-idea", "A lot of water evaporates, but it returns as rain.")], ["The water cycle moves the same water around again and again."], None)
q("wc-013", B, 2, WC, "Which of the following do plants use water for?", "To make their food", [W("To make sunlight", "wrong-idea", "Plants cannot make sunlight."), W("To make soil", "wrong-idea", "Plants do not make soil from water."), W("To keep warm at night", "wrong-idea", "Water is not used by plants as a blanket.")], ["Plants use water, light and carbon dioxide to make food."], None)
q("wc-014", B, 2, WC, "A plant was not watered for many days. Its leaves became soft and drooped. What is the most likely reason?", "The plant lost water", [W("The plant had too much sunlight", "wrong-idea", "Too much light does not make leaves droop by itself."), W("The plant had too much water", "reversed", "A plant with too much water does not droop like this."), W("The plant grew too many roots", "wrong-idea", "More roots would take in more water.")], ["Plants droop, or wilt, when they lose water."], None)
q("wc-015", B, 2, WC, "On a hot day, what does the body make to help it cool down?", "Sweat", [W("Urine", "wrong-term", "Urine is made to remove waste."), W("Saliva", "wrong-term", "Saliva is made in the mouth to help with eating."), W("Mucus", "wrong-term", "Mucus lines the nose and throat.")], ["Sweat is mostly water. It helps to cool the body."], None)
q("wc-016", B, 2, WC, "About how much of the human body is water?", "More than half of it", [W("About one tenth of it", "wrong-amount", "The body has much more water than this."), W("Almost none of it", "wrong-amount", "Water is a large part of the body."), W("Exactly all of it", "wrong-amount", "The body also has solid parts such as bones.")], ["Over half of the human body is water."], None)
q("wc-017", B, 3, WC, "Which of the following is a way to save water at home?", "Turning off the tap while brushing teeth", [W("Leaving the tap running while washing dishes", "wasting", "A running tap wastes a lot of water."), W("Washing a car with a running hose", "wasting", "A hose uses much more water than a bucket."), W("Flushing the toilet many times for no reason", "wasting", "Each flush uses clean water.")], ["Turning off the tap stops water from being wasted."], None)
q("wc-018", B, 3, WC, "Which action pollutes the water in a river?", "Pouring used cooking oil down a drain", [W("Picking up litter near the river bank", "helpful", "Removing litter keeps the river clean."), W("Planting trees along the river bank to hold soil", "helpful", "Trees do not pollute the river."), W("Using a bin for rubbish", "helpful", "Rubbish in a bin does not reach the river.")], ["Used oil flows to rivers and the sea and pollutes the water."], None)
q("wc-019", B, 3, WC, "A factory pours chemicals into a river. What is likely to happen to the fish in the river?", "Many of them may die", [W("They will grow bigger", "wrong-idea", "Chemicals harm living things."), W("They will move faster", "wrong-idea", "Polluted water does not make fish faster."), W("Nothing will happen to them", "wrong-idea", "Harmful chemicals can poison fish.")], ["Chemicals in water can poison fish and plants."], None)
q("wc-020", B, 3, WC, "Which of the following helps to keep water clean?", "Putting rubbish into a bin", [W("Throwing rubbish into a drain", "polluting", "Drains lead to rivers and the sea."), W("Washing paint brushes in a pond", "polluting", "Paint pollutes the water."), W("Pouring oil into the sea", "polluting", "Oil spills harm the sea.")], ["Rubbish in a bin cannot reach the water."], None)
q("wc-021", B, 3, WC, "What is NEWater?", "Used water cleaned so that it can be used again", [W("Rain water collected from roofs and drains", "wrong-idea", "NEWater is made from used water, not directly from rain."), W("Sea water that is sold with its salt left in", "wrong-idea", "Salt would make it unfit to drink."), W("Water that comes from a brand new tap", "wrong-idea", "NEWater is not named for a tap.")], ["NEWater is treated used water."], None)
q("wc-022", B, 3, WC, "Why should we not drink water straight from a dirty river?", "It may have germs that make us ill", [W("It is too heavy for our bodies to drink", "wrong-idea", "Dirty water is not heavier in a way that matters."), W("It has no real water in it at all", "wrong-idea", "River water is water, but it may be unsafe."), W("It makes our teeth much stronger", "wrong-idea", "Dirty water does not help teeth.")], ["Dirty water can carry germs that cause diseases."], None)
q("wc-023", B, 3, WC, "Which of the following wastes water?", "Letting the tap run while washing plates", [W("Using a basin of water to wash vegetables", "saving", "A basin uses less water than a running tap."), W("Using a bucket of water to wash a bicycle", "saving", "A bucket limits the water used."), W("Watering the plants with water used for rinsing rice", "saving", "Reusing water saves clean water.")], ["A running tap wastes water that could be saved."], None)
q("wc-024", B, 2, WC, "Which of the following is a water habitat?", "A pond", [W("A termite mound", "land-habitat", "A termite mound is on land."), W("A hole in a tree", "land-habitat", "A hole in a tree is on land."), W("A desert", "land-habitat", "A desert is very dry land.")], ["A pond is full of water and animals and plants live in it."], None)
q("wc-025", B, 3, RD, "The table shows how much water is used by some ways of washing. Which way uses the least water?", "Brushing teeth with the tap off", [W("Brushing teeth with the tap on", "reversed", "This used 12 litres, the most."), W("Washing the face with the tap on", "wrong-row", "This used 8 litres."), W("Washing the face with a basin", "wrong-row", "This used 2 litres, more than 1 litre.")], ["Tap off: 1 litre. This is the smallest amount."], tb(["Way of washing", "Water used (litres)"], [["Brushing teeth, tap on", "12"], ["Brushing teeth, tap off", "1"], ["Washing face, tap on", "8"], ["Washing face, basin", "2"]], [190, 140], "Water used by ways of washing"))

# ---------------- intermediate ----------------
q("wc-101", I, 1, WC, "Look at the picture of the water cycle. What happens at Q?", "Water vapour cools and forms tiny droplets", [W("Water from the sea changes into water vapour", "wrong-stage", "That is evaporation, which happens as water rises from the sea."), W("Tiny droplets of water change into ice", "wrong-idea", "No freezing is part of this picture."), W("Rain water flows into the river", "wrong-stage", "Water flowing down is run-off, not what happens in the cloud.")], ["Q is the cloud, where condensation takes place."], cy({"ev": "P", "co": "Q", "pr": "R", "ru": "S"}))
q("wc-102", I, 1, WC, "Look at the picture of the water cycle. Which two letters show stages in which water changes its state?", "R and P", [W("S and Q", "wrong-pair", "S and Q show water falling and flowing as a liquid, so the state is not changing."), W("R and S", "wrong-pair", "S shows water falling as a liquid."), W("P and Q", "wrong-pair", "Q shows water flowing as a liquid.")], ["R is evaporation and P is condensation. In both, water changes between gas and liquid."], cy({"ev": "R", "co": "P", "pr": "S", "ru": "Q"}))
q("wc-103", I, 1, WC, "Look at the picture of the water cycle. Which letter shows the stage that needs heat from the Sun?", "S", [W("P", "wrong-stage", "P is condensation, which happens when water vapour cools."), W("Q", "wrong-stage", "Q is rain, which falls because of its weight."), W("R", "wrong-stage", "R is run-off, which is driven by the slope of the land.")], ["Evaporation needs the Sun's heat. It is shown by S."], cy({"ev": "S", "co": "P", "pr": "Q", "ru": "R"}))
q("wc-104", I, 1, WC, "Over a large lake, the Sun's heat is blocked for many weeks by thick smoke. What is most likely to happen to the rain over the lake?", "There will be less rain", [W("There will be more rain", "reversed", "Less heat means less water evaporates, so fewer clouds form."), W("The rain will be the same", "wrong-idea", "The rain depends on how much water evaporates."), W("The rain will turn salty", "wrong-idea", "Rain does not take up salt from the lake.")], ["Less heat means less evaporation and fewer clouds."], None)
q("wc-105", I, 1, WC, "Look at the model of the water cycle. Why are ice cubes placed on the plastic sheet?", "They cool the vapour so that drops form", [W("They heat the water vapour in the bowl", "reversed", "Ice takes heat away."), W("They stop water vapour from forming", "wrong-idea", "Vapour forms from the hot water below."), W("They make the plastic sheet thicker and stronger", "wrong-idea", "The sheet stays the same thickness.")], ["Cold ice cools the sheet, so the vapour condenses to drops."], lambda: bowl("A model of the water cycle"))
q("wc-106", I, 1, WC, "Drops of water appear on the outside of a cold can in a warm room. Where did most of this water come from?", "Water vapour in the air", [W("Water that leaked through the can", "wrong-idea", "The can is not leaking. The drops form even on a sealed can."), W("Water that came out of the can's metal", "wrong-idea", "Metal does not hold water."), W("Water made by the cold can", "wrong-idea", "The can cannot make water.")], ["Water vapour in the warm air cooled at the can and condensed into drops."], can)
q("wc-107", I, 1, RD, "The bar graph shows the amount of rain in a town in six months. How much more rain fell in May than in March?", "40 mm", [W("100 mm", "wrong-read", "100 mm is the rain in May alone, not the difference."), W("60 mm", "wrong-read", "This is the rain in March alone."), W("160 mm", "added", "This adds the two months instead of finding the difference.")], ["May is 100 mm and March is 60 mm. 100 - 60 = 40 mm."], lambda: graph(["Jan", "Feb", "Mar", "Apr", "May", "Jun"], [("Rain", [120, 80, 60, 70, 100, 40])], 140, "Month", "Rain (mm)", "Rain in six months", 20, W=360, bars=True))
q("wc-108", I, 1, RD, "A pond had no rain on any day shown in the graph. What is the best reason for the fall in the water level?", "The Sun's heat made water evaporate", [W("The water condensed into rain in the pond", "reversed", "Condensation does not remove water from a pond."), W("Water vapour dropped into the pond", "reversed", "That would raise the level."), W("The pond made more water vapour at night", "wrong-idea", "The level fell steadily during the whole time.")], ["With no rain, water lost through evaporation lowers the level."], lambda: graph(["1", "2", "3", "4", "5"], [("Level", [50, 47, 44, 41, 38])], 60, "Day", "Water level (cm)", "Water level of a pond with no rain", 10, W=340))
q("wc-109", I, 3, RD, "A river was checked at three places for fish. The factory pipe is next to place B. What does the table suggest?", "Something harmful may have entered near B", [W("The river was the cleanest place at B", "reversed", "Place B has the fewest fish."), W("Fish prefer to live close to the factory pipe", "reversed", "There are fewer fish near the factory."), W("The river flows upwards to A", "wrong-idea", "The table says nothing about the flow.")], ["Fish fall from 24 at A to 9 at B, so pollution near B is likely."], tb(["Place", "Fish seen"], [["A (before the factory)", "24"], ["B (next to the pipe)", "9"], ["C (far downstream)", "15"]], [190, 100], "Fish seen in a river"))
