q("wc-123", I, 1, WC, "Look at the picture of the water cycle. At which letter does water lose heat as it changes into tiny droplets?", "R", [W("P", "wrong-stage", "P is rain falling."), W("Q", "wrong-stage", "Q is river water flowing."), W("S", "wrong-stage", "S is water vapour rising as it gains heat.")], ["Water vapour loses heat and condenses in the cloud, R."], cy({"ev": "S", "co": "R", "pr": "P", "ru": "Q"}))
q("wc-124", I, 1, RD, "The graph shows the water level in a reservoir at the end of each month. In which month did the reservoir gain the most water?", "April", [W("March", "wrong-read", "From February to March the level rose by only 2 m."), W("May", "wrong-read", "From April to May the level changed by 2 m."), W("June", "wrong-read", "From May to June the level fell.")], ["March to April: 8 m to 14 m. This is the biggest rise."], lambda: graph(["Feb", "Mar", "Apr", "May", "Jun"], [("Level", [6, 8, 14, 12, 9])], 16, "End of month", "Water level (m)", "Water level in a reservoir", 4, W=340))
q("wc-125", I, 1, WC, "A student wants more drops to form under the plastic sheet in the same time. Which change would help?", "Put more ice on top of the sheet", [W("Take the plastic sheet off the bowl", "wrong-change", "Vapour would escape instead of condensing."), W("Use cooler water in the bowl", "wrong-change", "Cooler water makes less water vapour."), W("Put a warm cloth on the sheet", "wrong-change", "A warm sheet cools the vapour less.")], ["More ice cools the sheet more, so more vapour condenses."], lambda: bowl("A model of the water cycle"))

# ---------------- competent ----------------
q("wc-201", C, 1, WC, "Look at the picture of the water cycle. Which statement is correct?", "Water vapour turns into tiny droplets at Q", [W("Water changes from gas to liquid at P", "wrong-stage", "At P, liquid water changes into water vapour."), W("Tiny droplets change into water vapour at R", "reversed", "At R the water is already falling as a liquid."), W("Water flows up the river at S", "wrong-idea", "River water flows down to the sea.")], ["P is evaporation, Q is condensation, R is rain, S is run-off."], cy())
